import { createReadStream } from 'node:fs';
import { chmod, copyFile, mkdir, rename, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { Readable } from 'node:stream';
import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { config } from '../config.js';
import { AppError, notFound } from './errors.js';

/**
 * Where uploaded documents live. Keys are generated by the server (never taken from user input). Files go in and out as
 * streams, so a document is never held in memory whole.
 */
export interface Storage {
  /** Stores a small in-memory file (seed data, generated documents). */
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** Moves a validated temporary upload into storage. */
  putFile(key: string, file: string, contentType: string, size: number): Promise<void>;
  stream(key: string): Promise<Readable>;
  remove(key: string): Promise<void>;
}

// Owner-only permissions (ignored on Windows, where the directory's ACL applies).
const DIR_MODE = 0o700, FILE_MODE = 0o600;

class LocalStorage implements Storage {
  private root = path.resolve(config.STORAGE_DIR);
  private file(key: string) {
    const p = path.resolve(this.root, key);
    if (!p.startsWith(this.root + path.sep)) throw new Error('Invalid storage key');
    return p;
  }
  private async target(key: string) {
    const p = this.file(key);
    await mkdir(path.dirname(p), { recursive: true, mode: DIR_MODE });
    return p;
  }
  async put(key: string, body: Buffer) {
    await writeFile(await this.target(key), body, { mode: FILE_MODE, flag: 'wx' });
  }
  async putFile(key: string, file: string) {
    const p = await this.target(key);
    try {
      await rename(file, p);
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== 'EXDEV') throw e;
      await copyFile(file, p); // temp dir on another disk
      await rm(file, { force: true });
    }
    await chmod(p, FILE_MODE);
  }
  async stream(key: string) {
    const p = this.file(key);
    await stat(p); // a missing file fails here, before any response is sent
    return createReadStream(p);
  }
  async remove(key: string) { await rm(this.file(key), { force: true }); }
}

export interface S3Limits {
  /** To open a connection. */
  connectMs: number;
  /** Longest silence on an open connection, while sending or receiving (a download's body included). */
  socketMs: number;
  /** The whole operation, retries included. For a download, up to the moment its body starts to arrive. */
  operationMs: number;
  /** Tries per operation, the first included. */
  maxAttempts: number;
  /** Backoff before retry n is a random time up to min(capMs, baseMs * 2^(n-1)) ("full jitter"). */
  backoffBaseMs: number;
  backoffCapMs: number;
}

export interface S3Options {
  bucket: string;
  region?: string;
  endpoint?: string;
  credentials?: { accessKeyId: string; secretAccessKey: string };
  limits: S3Limits;
}

// Network failures worth another try. Anything else without an HTTP status (bad configuration, a bug) is not.
const RETRYABLE_CODES = new Set(['ECONNRESET', 'ECONNREFUSED', 'ETIMEDOUT', 'EPIPE', 'EAI_AGAIN', 'ENETUNREACH', 'EHOSTUNREACH']);

/** Timeouts, throttling and server errors are worth retrying; a 4xx answer (missing object, denied, bad request) is not. */
export function isRetryable(err: unknown) {
  const e = err as { name?: string; code?: string; $retryable?: unknown; $metadata?: { httpStatusCode?: number } };
  if (e.name === 'AbortError') return false; // our own deadline for the whole operation has passed
  if (e.$retryable) return true;
  const status = e.$metadata?.httpStatusCode;
  if (status) return status >= 500 || status === 429;
  return e.name === 'TimeoutError' || e.name === 'RequestTimeout' || (!!e.code && RETRYABLE_CODES.has(e.code));
}

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * An S3-compatible bucket. Every call is bounded (connect, socket silence, whole operation) and retried a bounded
 * number of times with backoff and jitter, only when retrying can help. The SDK's own retries are off: an upload's
 * body is a file stream, which only a fresh stream per attempt can send again. Failures come out as AppErrors (404 for
 * a missing object, 503 otherwise), so a request fails cleanly and a job's error is logged and retried by the job.
 */
export class S3Storage implements Storage {
  private client: S3Client;
  private bucket: string;
  private limits: S3Limits;
  constructor(o: S3Options) {
    this.bucket = o.bucket;
    this.limits = o.limits;
    this.client = new S3Client({
      region: o.region || 'auto',
      endpoint: o.endpoint || undefined,
      forcePathStyle: !!o.endpoint,
      credentials: o.credentials,
      maxAttempts: 1,
      requestHandler: { connectionTimeout: o.limits.connectMs, socketTimeout: o.limits.socketMs },
    });
  }

  private async call<T>(op: string, key: string, attempt: (abortSignal: AbortSignal) => Promise<T>): Promise<T> {
    const deadline = new AbortController();
    const timer = setTimeout(() => deadline.abort(), this.limits.operationMs);
    try {
      for (let n = 1; ; n++) {
        try {
          return await attempt(deadline.signal);
        } catch (err) {
          if (n >= this.limits.maxAttempts || deadline.signal.aborted || !isRetryable(err)) throw storageError(op, key, err, deadline.signal.aborted, n);
          await sleep(Math.random() * Math.min(this.limits.backoffCapMs, this.limits.backoffBaseMs * 2 ** (n - 1)));
          if (deadline.signal.aborted) throw storageError(op, key, err, true, n);
        }
      }
    } finally {
      clearTimeout(timer); // once a download's body starts to arrive only socketMs applies, so a large file can finish
    }
  }

  async put(key: string, body: Buffer, contentType: string) {
    await this.call('put', key, abortSignal => this.client.send(
      new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: body, ContentType: contentType, ServerSideEncryption: 'AES256' }), { abortSignal }));
  }
  async putFile(key: string, file: string, contentType: string, size: number) {
    await this.call('put', key, async abortSignal => {
      // Streamed from disk, a fresh stream per attempt; the known length lets the SDK send it without buffering.
      const body = createReadStream(file);
      try {
        return await this.client.send(new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: body, ContentLength: size, ContentType: contentType, ServerSideEncryption: 'AES256' }), { abortSignal });
      } finally {
        body.destroy();
      }
    });
    await rm(file, { force: true });
  }
  async stream(key: string) {
    const r = await this.call('get', key, abortSignal => this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }), { abortSignal }));
    return r.Body as Readable;
  }
  async remove(key: string) {
    await this.call('delete', key, abortSignal => this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }), { abortSignal }));
  }
}

/** The error a caller sees: a missing object is a 404; anything else means storage is unavailable (503). Logged here. */
function storageError(op: string, key: string, err: unknown, timedOut: boolean, attempts: number) {
  const e = err as { name?: string; $metadata?: { httpStatusCode?: number } };
  const status = e.$metadata?.httpStatusCode;
  if (status === 404 || e.name === 'NoSuchKey') return notFound('Document');
  // Object keys are generated by the server and carry no personal data; credentials never appear in SDK errors.
  console.error(`Storage ${op} ${key} failed after ${attempts} attempt(s)${timedOut ? ' (timed out)' : ''}: ${e.name ?? 'Error'}${status ? ` ${status}` : ''} ${(err as Error).message ?? ''}`.trim());
  return new AppError(503, 'STORAGE_UNAVAILABLE', 'Document storage is not available right now. Please try again shortly.');
}

export const storage: Storage = config.STORAGE_DRIVER === 's3'
  ? new S3Storage({
    bucket: config.S3_BUCKET,
    region: config.S3_REGION,
    endpoint: config.S3_ENDPOINT,
    credentials: config.S3_ACCESS_KEY_ID ? { accessKeyId: config.S3_ACCESS_KEY_ID, secretAccessKey: config.S3_SECRET_ACCESS_KEY } : undefined,
    limits: {
      connectMs: config.S3_CONNECT_TIMEOUT_SECONDS * 1000,
      socketMs: config.S3_SOCKET_TIMEOUT_SECONDS * 1000,
      operationMs: config.S3_OPERATION_TIMEOUT_SECONDS * 1000,
      maxAttempts: config.S3_MAX_ATTEMPTS,
      backoffBaseMs: 200,
      backoffCapMs: 5_000,
    },
  })
  : new LocalStorage();
